CREATE TABLE IF NOT EXISTS public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL, phone text, avatar_path text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.user_roles (user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,role));
CREATE TABLE IF NOT EXISTS public.customers (id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, emergency_contact_name text NOT NULL, emergency_contact_phone text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.customer_addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE, label text NOT NULL, recipient_name text NOT NULL, phone text NOT NULL, address_line text NOT NULL, city text NOT NULL, province text NOT NULL, postal_code text, latitude numeric(9,6), longitude numeric(9,6), is_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90), CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS public.elder_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id) ON DELETE CASCADE, name text NOT NULL, date_of_birth date, gender text, conditions jsonb NOT NULL, allergies text, mobility text NOT NULL CHECK(mobility IN ('mandiri','butuh_bantuan','tirah_baring')), medical_notes text, photo_path text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(jsonb_typeof(conditions)='array' AND jsonb_array_length(conditions)>0));
CREATE TABLE IF NOT EXISTS public.elder_addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), elder_profile_id uuid NOT NULL REFERENCES public.elder_profiles(id) ON DELETE CASCADE, address_line text NOT NULL, city text NOT NULL, province text NOT NULL, postal_code text, latitude numeric(9,6) NOT NULL, longitude numeric(9,6) NOT NULL, access_notes text, is_default boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK(latitude BETWEEN -90 AND 90), CHECK(longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS public.caregivers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES public.profiles(id) ON DELETE SET NULL, legacy_caregiver_id integer NOT NULL UNIQUE CHECK(legacy_caregiver_id BETWEEN 1 AND 100), name text NOT NULL, role text NOT NULL, city text NOT NULL, area text NOT NULL, category text NOT NULL, gender text NOT NULL, age smallint CHECK(age BETWEEN 18 AND 100), languages jsonb NOT NULL, price_per_shift numeric(12,2) NOT NULL CHECK(price_per_shift>=0), rating numeric(2,1) NOT NULL CHECK(rating BETWEEN 0 AND 5), reviews_count integer NOT NULL DEFAULT 0 CHECK(reviews_count>=0), badge text, latitude numeric(9,6) NOT NULL, longitude numeric(9,6) NOT NULL, description text, photo_path text, is_active boolean NOT NULL DEFAULT true, source_payload jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(jsonb_typeof(languages)='array'), CHECK(latitude BETWEEN -90 AND 90), CHECK(longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS public.caregiver_availability (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), caregiver_id uuid NOT NULL REFERENCES public.caregivers(id) ON DELETE CASCADE, start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, status public.availability_status NOT NULL DEFAULT 'available', notes text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS public.bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id), caregiver_id uuid NOT NULL REFERENCES public.caregivers(id), elder_profile_id uuid NOT NULL REFERENCES public.elder_profiles(id), elder_address_id uuid NOT NULL REFERENCES public.elder_addresses(id), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, status public.booking_status NOT NULL DEFAULT 'pending', total_amount numeric(12,2) NOT NULL CHECK(total_amount>=0), address_snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(end_at>start_at));
CREATE TABLE IF NOT EXISTS public.live_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE CASCADE, report_date date NOT NULL, content jsonb NOT NULL, created_by uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES public.bookings(id) ON DELETE CASCADE, provider text NOT NULL DEFAULT 'demo' CHECK(provider='demo'), method public.payment_method NOT NULL, provider_reference text, amount numeric(12,2) NOT NULL CHECK(amount>=0), currency char(3) NOT NULL DEFAULT 'IDR', status public.payment_status NOT NULL DEFAULT 'unpaid', paid_at timestamptz, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
DO $$ BEGIN ALTER TABLE public.payments ADD CONSTRAINT payments_demo_provider CHECK(provider='demo'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL UNIQUE REFERENCES public.bookings(id) ON DELETE CASCADE, rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.sos_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES public.customers(id), elder_profile_id uuid NOT NULL REFERENCES public.elder_profiles(id), booking_id uuid REFERENCES public.bookings(id), emergency_number text NOT NULL CHECK(emergency_number IN ('112','119')), latitude numeric(9,6), longitude numeric(9,6), triggered_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'initiated', metadata jsonb, CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90), CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS public.booking_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id) ON DELETE CASCADE, from_status public.booking_status, to_status public.booking_status NOT NULL, actor_id uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, booking_id uuid REFERENCES public.bookings(id) ON DELETE CASCADE, type text NOT NULL, title text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS one_default_customer_address ON public.customer_addresses(customer_id) WHERE is_default;
CREATE UNIQUE INDEX IF NOT EXISTS one_default_elder_address ON public.elder_addresses(elder_profile_id) WHERE is_default;
ALTER TABLE public.caregiver_availability DROP CONSTRAINT IF EXISTS caregiver_availability_no_overlap;
ALTER TABLE public.caregiver_availability ADD CONSTRAINT caregiver_availability_no_overlap EXCLUDE USING gist(caregiver_id WITH =, tstzrange(start_at,end_at,'[)') WITH &&) WHERE(status='available');
ALTER TABLE public.bookings DROP CONSTRAINT IF EXISTS bookings_no_overlap;
ALTER TABLE public.bookings ADD CONSTRAINT bookings_no_overlap EXCLUDE USING gist(caregiver_id WITH =, tstzrange(start_at,end_at,'[)') WITH &&) WHERE(status IN ('pending','confirmed','in_progress'));
CREATE OR REPLACE FUNCTION public.validate_booking_links() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE a public.elder_addresses;
BEGIN
  IF NOT EXISTS(SELECT 1 FROM elder_profiles e WHERE e.id=NEW.elder_profile_id AND e.customer_id=NEW.customer_id) THEN RAISE EXCEPTION 'elder/customer mismatch'; END IF;
  SELECT * INTO a FROM elder_addresses WHERE id=NEW.elder_address_id AND elder_profile_id=NEW.elder_profile_id;
  IF a.id IS NULL THEN RAISE EXCEPTION 'elder address mismatch'; END IF;
  -- Server is source of truth; client address_snapshot is ignored.
  NEW.address_snapshot := jsonb_build_object('address_line',a.address_line,'city',a.city,'province',a.province,'postal_code',a.postal_code,'latitude',a.latitude,'longitude',a.longitude,'access_notes',a.access_notes);
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS bookings_validate_links ON public.bookings;
CREATE TRIGGER bookings_validate_links BEFORE INSERT OR UPDATE ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.validate_booking_links();
CREATE OR REPLACE FUNCTION public.is_role(wanted public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=auth.uid() AND role=wanted) $$;
REVOKE ALL ON FUNCTION public.is_role(public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_role(public.app_role) TO authenticated;
CREATE OR REPLACE FUNCTION public.transition_booking(p_booking uuid, p_to public.booking_status) RETURNS public.bookings LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE b public.bookings; old_status public.booking_status; uid uuid := auth.uid(); caregiver_user uuid;
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT * INTO b FROM public.bookings WHERE id=p_booking FOR UPDATE;
  IF b.id IS NULL THEN RAISE EXCEPTION 'booking not found'; END IF;
  SELECT user_id INTO caregiver_user FROM public.caregivers WHERE id=b.caregiver_id;
  old_status := b.status;
  IF NOT ((old_status,p_to) IN (('pending','confirmed'),('pending','cancelled'),('confirmed','in_progress'),('confirmed','cancelled'),('in_progress','completed'))) THEN RAISE EXCEPTION 'invalid booking transition'; END IF;
  IF NOT (public.is_role('admin') OR (p_to='confirmed' AND public.is_role('caregiver') AND caregiver_user=uid) OR (p_to='in_progress' AND public.is_role('caregiver') AND caregiver_user=uid) OR (p_to='completed' AND public.is_role('caregiver') AND caregiver_user=uid) OR (p_to='cancelled' AND ((public.is_role('customer') AND b.customer_id=uid) OR (public.is_role('caregiver') AND caregiver_user=uid)))) THEN RAISE EXCEPTION 'booking transition forbidden'; END IF;
  UPDATE public.bookings SET status=p_to,updated_at=now() WHERE id=p_booking RETURNING * INTO b;
  INSERT INTO public.booking_events(booking_id,from_status,to_status,actor_id) VALUES (b.id,old_status,p_to,uid); RETURN b;
END $$;
CREATE OR REPLACE FUNCTION public.transition_payment(p_payment uuid, p_to public.payment_status) RETURNS public.payments LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE p public.payments; old_status public.payment_status; uid uuid := auth.uid();
BEGIN
  IF uid IS NULL THEN RAISE EXCEPTION 'authentication required'; END IF;
  SELECT * INTO p FROM public.payments WHERE id=p_payment FOR UPDATE; IF p.id IS NULL THEN RAISE EXCEPTION 'payment not found'; END IF;
  IF NOT (public.is_role('admin') OR (public.is_role('customer') AND EXISTS(SELECT 1 FROM public.bookings b WHERE b.id=p.booking_id AND b.customer_id=uid))) THEN RAISE EXCEPTION 'payment transition forbidden'; END IF;
  old_status := p.status;
  IF NOT ((old_status,p_to) IN (('unpaid','pending'),('pending','paid_demo'),('pending','failed_demo'),('paid_demo','refunded_demo'))) THEN RAISE EXCEPTION 'invalid payment transition'; END IF;
  UPDATE payments SET status=p_to,paid_at=CASE WHEN p_to='paid_demo' THEN now() ELSE paid_at END,updated_at=now() WHERE id=p_payment RETURNING * INTO p; RETURN p;
END $$;
REVOKE ALL ON FUNCTION public.transition_booking(uuid,public.booking_status) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.transition_payment(uuid,public.payment_status) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.transition_booking(uuid,public.booking_status) TO authenticated;
GRANT EXECUTE ON FUNCTION public.transition_payment(uuid,public.payment_status) TO authenticated;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY; ALTER TABLE public.customer_addresses ENABLE ROW LEVEL SECURITY; ALTER TABLE public.elder_profiles ENABLE ROW LEVEL SECURITY; ALTER TABLE public.elder_addresses ENABLE ROW LEVEL SECURITY; ALTER TABLE public.caregivers ENABLE ROW LEVEL SECURITY; ALTER TABLE public.caregiver_availability ENABLE ROW LEVEL SECURITY; ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY; ALTER TABLE public.live_reports ENABLE ROW LEVEL SECURITY; ALTER TABLE public.payments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY; ALTER TABLE public.sos_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.booking_events ENABLE ROW LEVEL SECURITY; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
