CREATE POLICY caregivers_public_read ON public.caregivers FOR SELECT USING(is_active OR public.is_role('admin'));
CREATE POLICY booking_insert_customer ON public.bookings FOR INSERT WITH CHECK(customer_id=auth.uid() AND EXISTS(SELECT 1 FROM public.elder_profiles e WHERE e.id=elder_profile_id AND e.customer_id=auth.uid()));
CREATE POLICY booking_update_admin ON public.bookings FOR UPDATE USING(public.is_role('admin')) WITH CHECK(public.is_role('admin'));
CREATE POLICY profiles_self ON public.profiles FOR SELECT USING(id=auth.uid() OR public.is_role('admin'));
CREATE POLICY roles_self ON public.user_roles FOR SELECT USING(user_id=auth.uid() OR public.is_role('admin'));
CREATE POLICY customer_self ON public.customers USING(id=auth.uid() OR public.is_role('admin')) WITH CHECK(id=auth.uid() OR public.is_role('admin'));
CREATE POLICY elder_owner ON public.elder_profiles USING(customer_id=auth.uid() OR public.is_role('admin')) WITH CHECK(customer_id=auth.uid() OR public.is_role('admin'));
CREATE POLICY booking_read_owner_or_assignee ON public.bookings FOR SELECT USING(customer_id=auth.uid() OR caregiver_id IN(SELECT id FROM caregivers WHERE user_id=auth.uid()) OR public.is_role('admin'));
