CREATE POLICY report_insert_assigned ON public.live_reports FOR INSERT WITH CHECK(created_by=auth.uid() AND EXISTS(SELECT 1 FROM bookings b JOIN caregivers c ON c.id=b.caregiver_id WHERE b.id=booking_id AND c.user_id=auth.uid()));
