CREATE POLICY review_read_owner ON public.reviews FOR SELECT USING(EXISTS(SELECT 1 FROM bookings b WHERE b.id=booking_id AND (b.customer_id=auth.uid() OR b.caregiver_id IN(SELECT id FROM caregivers WHERE user_id=auth.uid()) OR public.is_role('admin'))));
CREATE POLICY notification_self ON public.notifications FOR SELECT USING(user_id=auth.uid() OR public.is_role('admin'));
CREATE POLICY customer_addresses_read ON public.customer_addresses FOR SELECT USING(customer_id=auth.uid() OR public.is_role('admin'));
