CREATE POLICY elder_addresses_read ON public.elder_addresses FOR SELECT USING(EXISTS(SELECT 1 FROM public.elder_profiles e WHERE e.id=elder_profile_id AND (e.customer_id=auth.uid() OR public.is_role('admin'))));
CREATE POLICY elder_addresses_insert ON public.elder_addresses FOR INSERT WITH CHECK(EXISTS(SELECT 1 FROM elder_profiles e WHERE e.id=elder_profile_id AND (e.customer_id=auth.uid() OR public.is_role('admin'))));
