CREATE POLICY availability_owner_update ON public.caregiver_availability FOR UPDATE USING(caregiver_id IN(SELECT id FROM caregivers WHERE user_id=auth.uid()) OR public.is_role('admin')) WITH CHECK(caregiver_id IN(SELECT id FROM caregivers WHERE user_id=auth.uid()) OR public.is_role('admin'));
CREATE POLICY availability_owner_delete ON public.caregiver_availability FOR DELETE USING(caregiver_id IN(SELECT id FROM caregivers WHERE user_id=auth.uid()) OR public.is_role('admin'));
CREATE POLICY payment_owner_read ON public.payments FOR SELECT USING(EXISTS(SELECT 1 FROM bookings b WHERE b.id=booking_id AND (b.customer_id=auth.uid() OR b.caregiver_id IN(SELECT id FROM caregivers WHERE user_id=auth.uid()) OR public.is_role('admin'))));
CREATE POLICY payment_owner_insert ON public.payments FOR INSERT WITH CHECK(EXISTS(SELECT 1 FROM bookings b WHERE b.id=booking_id AND b.customer_id=auth.uid()));
CREATE POLICY sos_owner_read ON public.sos_events FOR SELECT USING(customer_id=auth.uid() OR public.is_role('admin'));
CREATE POLICY sos_owner_insert ON public.sos_events FOR INSERT WITH CHECK(customer_id=auth.uid() OR public.is_role('admin'));
CREATE POLICY booking_events_owner_read ON public.booking_events FOR SELECT USING(EXISTS(SELECT 1 FROM bookings b WHERE b.id=booking_id AND (b.customer_id=auth.uid() OR b.caregiver_id IN(SELECT id FROM caregivers WHERE user_id=auth.uid()) OR public.is_role('admin'))));
CREATE POLICY report_update_assigned ON public.live_reports FOR UPDATE USING(created_by=auth.uid() AND EXISTS(SELECT 1 FROM bookings b JOIN caregivers c ON c.id=b.caregiver_id WHERE b.id=booking_id AND c.user_id=auth.uid())) WITH CHECK(created_by=auth.uid() AND EXISTS(SELECT 1 FROM bookings b JOIN caregivers c ON c.id=b.caregiver_id WHERE b.id=booking_id AND c.user_id=auth.uid()));
